CREATE TABLE pms_estate_budget (id BIGINT NOT NULL AUTO_INCREMENT,uuid BINARY(16) NOT NULL,created_on DATETIME(6),active BIT NOT NULL,created_by BIGINT,last_modified_date DATETIME(6),property_id BIGINT NOT NULL,budget_year INT NOT NULL,name VARCHAR(120) NOT NULL,currency VARCHAR(12) NOT NULL,status VARCHAR(30) NOT NULL,approved_at DATETIME(6),approved_by BIGINT,PRIMARY KEY(id),UNIQUE KEY uk_estate_budget_uuid(uuid),UNIQUE KEY uk_estate_budget_property_year_name(property_id,budget_year,name));
CREATE TABLE pms_estate_budget_line (id BIGINT NOT NULL AUTO_INCREMENT,uuid BINARY(16) NOT NULL,created_on DATETIME(6),active BIT NOT NULL,created_by BIGINT,last_modified_date DATETIME(6),budget_id BIGINT NOT NULL,category VARCHAR(80) NOT NULL,description VARCHAR(500),planned_amount DECIMAL(19,2) NOT NULL,actual_amount DECIMAL(19,2) NOT NULL DEFAULT 0.00,PRIMARY KEY(id),UNIQUE KEY uk_estate_budget_line_uuid(uuid),KEY idx_estate_budget_line_budget(budget_id,active),CONSTRAINT fk_estate_budget_line_budget FOREIGN KEY(budget_id) REFERENCES pms_estate_budget(id),CONSTRAINT chk_estate_budget_line_amounts CHECK(planned_amount >= 0 AND actual_amount >= 0));
CREATE TABLE pms_estate_meeting (id BIGINT NOT NULL AUTO_INCREMENT,uuid BINARY(16) NOT NULL,created_on DATETIME(6),active BIT NOT NULL,created_by BIGINT,last_modified_date DATETIME(6),property_id BIGINT NOT NULL,title VARCHAR(160) NOT NULL,scheduled_at DATETIME(6) NOT NULL,venue VARCHAR(255),status VARCHAR(30) NOT NULL,quorum_required INT NOT NULL DEFAULT 0,attendee_count INT NOT NULL DEFAULT 0,minutes VARCHAR(5000),PRIMARY KEY(id),UNIQUE KEY uk_estate_meeting_uuid(uuid),KEY idx_estate_meeting_property(property_id,scheduled_at));
CREATE TABLE pms_estate_resolution (id BIGINT NOT NULL AUTO_INCREMENT,uuid BINARY(16) NOT NULL,created_on DATETIME(6),active BIT NOT NULL,created_by BIGINT,last_modified_date DATETIME(6),meeting_id BIGINT NOT NULL,title VARCHAR(200) NOT NULL,decision VARCHAR(3000),status VARCHAR(30) NOT NULL,votes_for INT NOT NULL DEFAULT 0,votes_against INT NOT NULL DEFAULT 0,votes_abstain INT NOT NULL DEFAULT 0,due_date DATE,implemented_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_estate_resolution_uuid(uuid),KEY idx_estate_resolution_meeting(meeting_id,status),CONSTRAINT fk_estate_resolution_meeting FOREIGN KEY(meeting_id) REFERENCES pms_estate_meeting(id));
CREATE TABLE pms_estate_work_order (id BIGINT NOT NULL AUTO_INCREMENT,uuid BINARY(16) NOT NULL,created_on DATETIME(6),active BIT NOT NULL,created_by BIGINT,last_modified_date DATETIME(6),work_order_number VARCHAR(40) NOT NULL,property_id BIGINT NOT NULL,area_name VARCHAR(120) NOT NULL,title VARCHAR(160) NOT NULL,description VARCHAR(2000) NOT NULL,category VARCHAR(50) NOT NULL,priority VARCHAR(20) NOT NULL,status VARCHAR(30) NOT NULL,assigned_provider_service_id BIGINT,scheduled_at DATETIME(6),completed_at DATETIME(6),estimated_cost DECIMAL(19,2),actual_cost DECIMAL(19,2),currency VARCHAR(12),resolution_notes VARCHAR(1000),PRIMARY KEY(id),UNIQUE KEY uk_estate_work_order_uuid(uuid),UNIQUE KEY uk_estate_work_order_number(work_order_number),KEY idx_estate_work_order_property(property_id,status,active));
